/* AUTO-GENERATED by `npm run notes`. Do not edit by hand. */
import type { MDXProps } from 'mdx/types';

export type NoteModule = {
  default: (props: MDXProps) => React.JSX.Element;
};

/** "<section>/<noteSlug>" -> dynamic import of that MDX note. */
export const notes: Record<string, () => Promise<NoteModule>> = {
  'dsa/arrays-hashing': () => import('@content/dsa/arrays-hashing.mdx'),
  'dsa/dp-1d': () => import('@content/dsa/dp-1d.mdx'),
  'dsa/dp-bitmask': () => import('@content/dsa/dp-bitmask.mdx'),
  'dsa/dp-digit': () => import('@content/dsa/dp-digit.mdx'),
  'dsa/dp-grid': () => import('@content/dsa/dp-grid.mdx'),
  'dsa/dp-interval': () => import('@content/dsa/dp-interval.mdx'),
  'dsa/dp-knapsack': () => import('@content/dsa/dp-knapsack.mdx'),
  'dsa/dp-lis': () => import('@content/dsa/dp-lis.mdx'),
  'dsa/dp-string': () => import('@content/dsa/dp-string.mdx'),
  'dsa/dp-trees': () => import('@content/dsa/dp-trees.mdx'),
  'dsa/graph-traversal': () => import('@content/dsa/graph-traversal.mdx'),
  'dsa/mst': () => import('@content/dsa/mst.mdx'),
  'dsa/segment-tree': () => import('@content/dsa/segment-tree.mdx'),
  'dsa/shortest-paths': () => import('@content/dsa/shortest-paths.mdx'),
  'dsa/strings': () => import('@content/dsa/strings.mdx'),
  'dsa/topological-sort': () => import('@content/dsa/topological-sort.mdx'),
  'dsa/union-find': () => import('@content/dsa/union-find.mdx'),
};

export function hasNote(section: string, slug: string | null): boolean {
  return Boolean(slug && `${section}/${slug}` in notes);
}

export async function loadNote(section: string, slug: string | null) {
  if (!slug) return null;
  const loader = notes[`${section}/${slug}`];
  if (!loader) return null;
  return (await loader()).default;
}
